sys_script_include.script:
var WhatIfSimulationEngine = Class.create();
WhatIfSimulationEngine.prototype = {
    initialize: function() {
        this.PO = "x_2056099_indust_0_production_order";
        this.SCHED = "x_2056099_indust_0_prod_sched";
        this.RES = "x_2056099_indust_0_prod_res";
        this.SCENARIO = "x_2056099_indust_0_sim_scenario";
        this.RUN = "x_2056099_indust_0_sim_schedule_run";
        this.PM = "x_2056099_indust_0_production_material";
        this.STOCK = "x_2056099_indust_0_inv_stock";
        this.VALID_TYPES = ["resource_down", "capacity_reduction", "quantity_change", "material_shortage", "schedule_shift"];
    },

    simulate: function(params) {
        if (!params || !params.scenario_type) {
            return this._fail("scenario_type is required. Supported: " + this.VALID_TYPES.join(", "));
        }
        // [HackNow critical features] additional scenario types live in WhatIfScenarios
        var extra = new x_2056099_indust_0.WhatIfScenarios();
        if (extra.supports(params.scenario_type)) return extra.simulate(params);
        if (this.VALID_TYPES.indexOf(params.scenario_type) === -1) {
            return this._fail("Unsupported scenario_type: " + params.scenario_type + ". Supported: " + this.VALID_TYPES.join(", "));
        }

        switch (params.scenario_type) {
            case "resource_down":       return this._simulateResourceDown(params);
            case "capacity_reduction":  return this._simulateCapacityReduction(params);
            case "quantity_change":     return this._simulateQuantityChange(params);
            case "material_shortage":   return this._simulateMaterialShortage(params);
            case "schedule_shift":      return this._simulateScheduleShift(params);
            default: return this._fail("Unhandled scenario type");
        }
    },

    // ═══════════════════════════════════════
    // RESOURCE DOWN
    // ═══════════════════════════════════════
    _simulateResourceDown: function(params) {
        var resId = params.resource_id || "";
        if (!resId) return this._fail("resource_id is required for resource_down scenario");

        var res = new GlideRecord(this.RES);
        if (!res.get(resId)) return this._fail("Resource not found: " + resId);
        var resName = res.getValue("resource_name");

        // Find active schedules on this resource (READ-ONLY)
        var affected = this._getActiveSchedulesForResource(resId);

        // Find alternate resources (READ-ONLY)
        var alternates = this._findAlternateResources(resId);

        // Build adaptive proposals with proposed dates and delivery feasibility
        var proposals = [];
        for (var i = 0; i < affected.length; i++) {
            var sched = affected[i];
            var proposal = { schedule_sys_id: sched.sys_id, po_number: sched.po_number, current_resource: resName, proposed_action: "reschedule" };
            if (alternates.length > 0) {
                var alt = alternates[0];
                var newDays = this._calcDays(sched.planned_quantity, alt.capacity_per_day, alt.efficiency);
                proposal.proposed_resource = alt.resource_name;
                proposal.proposed_resource_id = alt.sys_id;
                proposal.simulated_duration_days = newDays;
                proposal.capacity_available = alt.capacity_per_day;

                // Virtual proposed schedule dates (in-memory only, never written to prod_sched)
                if (sched.planned_start) {
                    var pStart = new GlideDateTime(sched.planned_start);
                    var pEnd = new GlideDateTime(sched.planned_start);
                    pEnd.addDaysLocalTime(newDays);
                    proposal.proposed_start = pStart.getValue();
                    proposal.proposed_end = pEnd.getValue();
                }

                // Delivery deadline: customer_order.requested_delivery_date, else PO planned_end
                var deadline = sched.delivery_deadline || "";
                proposal.delivery_deadline = deadline;

                // Delivery feasibility
                if (deadline && proposal.proposed_end) {
                    var deadlineGdt = new GlideDateTime(deadline);
                    var proposedEndGdt = new GlideDateTime(proposal.proposed_end);
                    var onTime = proposedEndGdt.compareTo(deadlineGdt) <= 0;
                    proposal.delivery_feasible = onTime;
                    proposal.delivery_status = onTime ? "On Time" : "Late";
                    if (onTime) {
                        proposal.delay_days = 0;
                    } else {
                        var diffMs = GlideDateTime.subtract(deadlineGdt, proposedEndGdt).getNumericValue();
                        proposal.delay_days = Math.ceil(diffMs / (1000 * 60 * 60 * 24));
                    }
                } else {
                    proposal.delivery_feasible = null;
                    proposal.delivery_status = "No Deadline";
                    proposal.delay_days = 0;
                }
            } else {
                proposal.proposed_resource = "NONE_AVAILABLE";
                proposal.proposed_action = "manual_review";
                proposal.delivery_feasible = null;
                proposal.delivery_status = "No Deadline";
                proposal.delay_days = 0;
            }
            proposals.push(proposal);
        }

        // Create sim_scenario record
        var scenarioId = this._createScenario({
            scenario_name: "Resource Down: " + resName,
            disruption_category: "machine_breakdown",
            target_entity: resName,
            disruption_parameter: "Resource " + resName + " taken offline",
            impacted_order_count: affected.length,
            recommended_strategy: alternates.length > 0 ? "Reschedule to " + alternates[0].resource_name : "Manual review required"
        });

        // Create sim_schedule_run records
        for (var j = 0; j < affected.length; j++) {
            this._createRunRecord(scenarioId, affected[j], proposals[j] || {});
        }

        return {
            success: true,
            scenario_type: "resource_down",
            scenario_sys_id: scenarioId,
            resource_affected: resName,
            impacted_schedules: affected.length,
            alternate_resources_available: alternates.length,
            affected_orders: affected,
            alternateResources: alternates,
            adaptiveProposals: proposals,
            message: affected.length > 0 ? affected.length + " schedule(s) impacted by " + resName + " going down." : "No active schedules on this resource."
        };
    },

    // ═══════════════════════════════════════
    // CAPACITY REDUCTION
    // ═══════════════════════════════════════
    _simulateCapacityReduction: function(params) {
        var resId = params.resource_id || "";
        var reductionPct = parseFloat(params.reduction_percentage) || 50;
        if (!resId) return this._fail("resource_id is required for capacity_reduction scenario");
        if (reductionPct <= 0 || reductionPct >= 100) return this._fail("reduction_percentage must be between 1 and 99");

        var res = new GlideRecord(this.RES);
        if (!res.get(resId)) return this._fail("Resource not found: " + resId);
        var resName = res.getValue("resource_name");
        var currentCapacity = parseFloat(res.getValue("capacity_per_day")) || 0;
        var currentEfficiency = parseFloat(res.getValue("efficiency_percentage")) || 100;
        var simulatedCapacity = currentCapacity * (1 - reductionPct / 100);

        var affected = this._getActiveSchedulesForResource(resId);
        var impacts = [];
        for (var i = 0; i < affected.length; i++) {
            var sched = affected[i];
            var originalDays = this._calcDays(sched.planned_quantity, currentCapacity, currentEfficiency);
            var newDays = this._calcDays(sched.planned_quantity, simulatedCapacity, currentEfficiency);
            impacts.push({
                schedule_sys_id: sched.sys_id,
                po_number: sched.po_number,
                planned_quantity: sched.planned_quantity,
                original_duration_days: originalDays,
                simulated_duration_days: newDays,
                additional_days: newDays - originalDays,
                delay_impact: (newDays - originalDays) + " additional day(s) needed"
            });
        }

        var scenarioId = this._createScenario({
            scenario_name: "Capacity Reduction: " + resName + " by " + reductionPct + "%",
            disruption_category: "machine_breakdown",
            target_entity: resName,
            disruption_parameter: "Capacity reduced from " + currentCapacity + " to " + simulatedCapacity.toFixed(1) + " units/day (" + reductionPct + "% reduction)",
            impacted_order_count: affected.length,
            recommended_strategy: "Extend schedule durations or redistribute load"
        });

        return {
            success: true,
            scenario_type: "capacity_reduction",
            scenario_sys_id: scenarioId,
            resource: resName,
            current_capacity: currentCapacity,
            simulated_capacity: parseFloat(simulatedCapacity.toFixed(1)),
            reduction_percentage: reductionPct,
            impacted_schedules: affected.length,
            impacts: impacts,
            message: "Capacity reduction of " + reductionPct + "% on " + resName + " affects " + affected.length + " schedule(s)."
        };
    },

    // ═══════════════════════════════════════
    // QUANTITY CHANGE
    // ═══════════════════════════════════════
    _simulateQuantityChange: function(params) {
        var poId = params.production_order_id || "";
        var newQty = parseFloat(params.new_quantity) || 0;
        if (!poId) return this._fail("production_order_id is required for quantity_change scenario");
        if (newQty <= 0) return this._fail("new_quantity must be positive");

        var po = new GlideRecord(this.PO);
        if (!po.get(poId)) return this._fail("Production order not found: " + poId);
        var poNumber = po.getValue("number");
        var originalQty = parseFloat(po.getValue("quantity_planned")) || 0;
        var qtyDelta = newQty - originalQty;

        // Find active schedule
        var schedGr = new GlideRecord(this.SCHED);
        schedGr.addQuery("production_order", poId);
        schedGr.addQuery("status", "IN", "draft,scheduled,confirmed,in_progress");
        schedGr.setLimit(1);
        schedGr.query();

        var schedInfo = null;
        var originalDays = 0;
        var newDays = 0;
        if (schedGr.next()) {
            var resId = schedGr.getValue("production_resource");
            var resGr = new GlideRecord(this.RES);
            var cap = 1; var eff = 100;
            if (resGr.get(resId)) {
                cap = parseFloat(resGr.getValue("capacity_per_day")) || 1;
                eff = parseFloat(resGr.getValue("efficiency_percentage")) || 100;
            }
            originalDays = this._calcDays(originalQty, cap, eff);
            newDays = this._calcDays(newQty, cap, eff);
            schedInfo = {
                sys_id: schedGr.getValue("sys_id"),
                status: schedGr.getValue("status"),
                resource: resGr.getValue("resource_name"),
                original_duration_days: originalDays,
                simulated_duration_days: newDays,
                additional_days: newDays - originalDays
            };
        }

        var scenarioId = this._createScenario({
            scenario_name: "Quantity Change: " + poNumber + " from " + originalQty + " to " + newQty,
            disruption_category: "urgent_order_ingestion",
            target_entity: poNumber,
            disruption_parameter: "Quantity " + (qtyDelta > 0 ? "increased" : "decreased") + " by " + Math.abs(qtyDelta) + " units",
            impacted_order_count: 1,
            recommended_strategy: qtyDelta > 0 ? "Extend schedule or add resource" : "Schedule may complete earlier"
        });

        return {
            success: true,
            scenario_type: "quantity_change",
            scenario_sys_id: scenarioId,
            production_order: poNumber,
            original_quantity: originalQty,
            simulated_quantity: newQty,
            quantity_delta: qtyDelta,
            schedule_impact: schedInfo,
            message: "Quantity change from " + originalQty + " to " + newQty + " for " + poNumber + ". " + (schedInfo ? "Duration changes from " + originalDays + " to " + newDays + " day(s)." : "No active schedule found.")
        };
    },

    // ═══════════════════════════════════════
    // MATERIAL SHORTAGE
    // ═══════════════════════════════════════
    _simulateMaterialShortage: function(params) {
        var materialId = params.material_id || "";
        var shortageQty = parseFloat(params.shortage_quantity) || 0;
        if (!materialId) return this._fail("material_id is required for material_shortage scenario");
        if (shortageQty <= 0) return this._fail("shortage_quantity must be positive");

        var mat = new GlideRecord("x_2056099_indust_0_mat_master");
        if (!mat.get(materialId)) return this._fail("Material not found: " + materialId);
        var matName = mat.getValue("name");

        // Check current inventory (READ-ONLY)
        var stockGr = new GlideRecord(this.STOCK);
        stockGr.addQuery("material_product", materialId);
        stockGr.addQuery("active", true);
        stockGr.query();
        var totalAvailable = 0;
        while (stockGr.next()) {
            totalAvailable += parseFloat(stockGr.getValue("available_quantity")) || 0;
        }

        // Find production orders using this material (READ-ONLY)
        var pmGr = new GlideRecord(this.PM);
        pmGr.addQuery("material_product", materialId);
        pmGr.query();
        var affectedPOs = [];
        while (pmGr.next()) {
            var poid = pmGr.getValue("production_order");
            var poGr = new GlideRecord(this.PO);
            if (poGr.get(poid) && poGr.getValue("status") !== "completed" && poGr.getValue("status") !== "cancelled") {
                affectedPOs.push({
                    po_sys_id: poid,
                    po_number: poGr.getValue("number"),
                    po_status: poGr.getValue("status"),
                    required_qty: parseFloat(pmGr.getValue("required_quantity")) || 0
                });
            }
        }

        // Also check POs where material is the finished_product
        var poByProduct = new GlideRecord(this.PO);
        poByProduct.addQuery("finished_product", materialId);
        poByProduct.addQuery("status", "NOT IN", "completed,cancelled");
        poByProduct.query();
        while (poByProduct.next()) {
            var exists = false;
            for (var x = 0; x < affectedPOs.length; x++) {
                if (affectedPOs[x].po_sys_id === poByProduct.getValue("sys_id")) { exists = true; break; }
            }
            if (!exists) {
                affectedPOs.push({
                    po_sys_id: poByProduct.getValue("sys_id"),
                    po_number: poByProduct.getValue("number"),
                    po_status: poByProduct.getValue("status"),
                    required_qty: parseFloat(poByProduct.getValue("quantity_planned")) || 0
                });
            }
        }

        var simulatedAvailable = Math.max(0, totalAvailable - shortageQty);

        // ═══════════════════════════════════════
        // Per-order fulfillment impact via evaluateReadOnly (READ-ONLY)
        // ═══════════════════════════════════════
        var fulfillmentImpacts = [];
        var feasibleCount = 0, unfulfillableCount = 0, transferCount = 0;
        var procurementCount = 0, manualReviewCount = 0;
        var decisionEngine = new x_2056099_indust_0.MaterialFulfillmentDecision();

        for (var fi = 0; fi < affectedPOs.length; fi++) {
            var apo = affectedPOs[fi];
            // Resolve fulfillment_location and customer deadline from the PO
            var fiPo = new GlideRecord(this.PO);
            if (!fiPo.get(apo.po_sys_id)) continue;
            var fiWhId = fiPo.getValue("fulfillment_location") || "";
            if (!fiWhId) continue;
            var fiCoId = fiPo.getValue("customer_order") || "";
            var fiCustDate = "";
            if (fiCoId) {
                var fiCo = new GlideRecord("x_2056099_indust_0_cust_order");
                if (fiCo.get(fiCoId)) fiCustDate = fiCo.getValue("requested_delivery_date") || "";
            }
            if (!fiCustDate) fiCustDate = fiPo.getValue("planned_end_date") || "";

            // ONLY evaluateReadOnly — never evaluate()
            var roResult = decisionEngine.evaluateReadOnly({
                materialSysId: materialId,
                quantityRequired: apo.required_qty || 1,
                warehouseSysId: fiWhId,
                customerRequiredDate: fiCustDate,
                customerOrderSysId: fiCoId,
                productionOrderSysId: apo.po_sys_id
            });

            var impact = {
                production_order: apo.po_number,
                production_order_sys_id: apo.po_sys_id,
                material: matName,
                material_sys_id: materialId,
                required_quantity: apo.required_qty,
                fulfillment_warehouse: fiPo.getDisplayValue("fulfillment_location")
            };

            if (roResult && roResult.success) {
                impact.available_quantity = roResult.available_quantity;
                impact.reserved_quantity = roResult.reserved_quantity;
                impact.incoming_quantity = roResult.incoming_quantity;
                impact.shortage_quantity = roResult.shortage_quantity;
                impact.decision_type = roResult.decision_type;
                impact.feasible = roResult.feasible;
                impact.source_warehouse = roResult.source_warehouse || "";
                impact.supplier = roResult.supplier || "";
                impact.transfer_lead_time_days = roResult.transfer_lead_time_days || 0;
                impact.supplier_lead_time_days = roResult.supplier_lead_time_days || 0;
                impact.expected_fulfillment_date = roResult.expected_fulfillment_date || "";
                impact.customer_required_date = fiCustDate;
                impact.reason = roResult.reason || "";
                impact.recommended_action = roResult.recommended_action || "";

                if (roResult.feasible) feasibleCount++;
                var dt = roResult.decision_type || "";
                if (dt === "UNFULFILLABLE") unfulfillableCount++;
                else if (dt === "INTER_WAREHOUSE_TRANSFER") transferCount++;
                else if (dt === "PROCUREMENT_LOCAL_SUPPLIER" || dt === "PROCUREMENT_ALTERNATE_WAREHOUSE_SUPPLIER") procurementCount++;
                else if (dt === "MANUAL_REVIEW") manualReviewCount++;
            } else {
                impact.decision_type = "EVALUATION_FAILED";
                impact.feasible = false;
                impact.reason = (roResult && roResult.error) ? roResult.error : "evaluateReadOnly failed";
                impact.recommended_action = "Manual review required";
                manualReviewCount++;
            }
            fulfillmentImpacts.push(impact);
        }

        // Determine recommended strategy from read-only results
        var strategy;
        if (unfulfillableCount > 0 || manualReviewCount > 0) {
            strategy = unfulfillableCount + " unfulfillable, " + manualReviewCount + " manual review — procurement or substitution required";
        } else if (transferCount > 0 && transferCount === fulfillmentImpacts.length) {
            strategy = "All " + transferCount + " order(s) fulfillable via inter-warehouse transfer";
        } else if (feasibleCount === fulfillmentImpacts.length) {
            strategy = "All " + feasibleCount + " order(s) fulfillable from existing stock or supply";
        } else if (procurementCount > 0) {
            strategy = procurementCount + " order(s) require procurement; " + feasibleCount + " feasible";
        } else {
            strategy = simulatedAvailable > 0 ? "Partial fulfillment possible" : "Procurement or substitution required";
        }

        var scenarioId = this._createScenario({
            scenario_name: "Material Shortage: " + matName + " (-" + shortageQty + " units)",
            disruption_category: "material_shortage",
            target_entity: matName,
            disruption_parameter: "Shortage of " + shortageQty + " units. Available: " + totalAvailable + " -> Simulated: " + simulatedAvailable,
            impacted_order_count: affectedPOs.length,
            recommended_strategy: strategy
        });

        return {
            success: true,
            scenario_type: "material_shortage",
            scenario_sys_id: scenarioId,
            material: matName,
            material_id: materialId,
            current_available: totalAvailable,
            shortage_quantity: shortageQty,
            simulated_available: simulatedAvailable,
            affected_production_orders: affectedPOs,
            impacted_order_count: affectedPOs.length,
            fulfillment_impacts: fulfillmentImpacts,
            fulfillment_impact_count: fulfillmentImpacts.length,
            feasible_impact_count: feasibleCount,
            unfulfillable_impact_count: unfulfillableCount,
            transfer_impact_count: transferCount,
            procurement_impact_count: procurementCount,
            manual_review_impact_count: manualReviewCount,
            message: "Material shortage of " + shortageQty + " units for " + matName + ". " + affectedPOs.length + " production order(s) potentially affected. " + feasibleCount + " feasible, " + transferCount + " via transfer."
        };
    },

    // ═══════════════════════════════════════
    // SCHEDULE SHIFT
    // ═══════════════════════════════════════
    _simulateScheduleShift: function(params) {
        var schedId = params.schedule_id || "";
        var shiftDays = parseInt(params.shift_days) || 0;
        if (!schedId) return this._fail("schedule_id is required for schedule_shift scenario");
        if (shiftDays === 0) return this._fail("shift_days must be non-zero (positive=delay, negative=advance)");

        var sched = new GlideRecord(this.SCHED);
        if (!sched.get(schedId)) return this._fail("Schedule not found: " + schedId);

        var originalStart = sched.getValue("planned_start");
        var originalEnd = sched.getValue("planned_end");
        var schedStatus = sched.getValue("status");

        var poGr = new GlideRecord(this.PO);
        var poNumber = "";
        if (poGr.get(sched.getValue("production_order"))) {
            poNumber = poGr.getValue("number");
        }

        // Calculate simulated dates (DO NOT write)
        var simStart = new GlideDateTime(originalStart);
        simStart.addDaysLocalTime(shiftDays);
        var simEnd = new GlideDateTime(originalEnd);
        simEnd.addDaysLocalTime(shiftDays);

        // Check if shift causes resource conflict
        var resId = sched.getValue("production_resource");
        var conflictsFound = [];
        var otherScheds = new GlideRecord(this.SCHED);
        otherScheds.addQuery("production_resource", resId);
        otherScheds.addQuery("sys_id", "!=", schedId);
        otherScheds.addQuery("status", "IN", "draft,scheduled,confirmed,in_progress");
        otherScheds.query();
        while (otherScheds.next()) {
            var oStart = new GlideDateTime(otherScheds.getValue("planned_start"));
            var oEnd = new GlideDateTime(otherScheds.getValue("planned_end"));
            if (simStart.compareTo(oEnd) < 0 && simEnd.compareTo(oStart) > 0) {
                conflictsFound.push({ sys_id: otherScheds.getValue("sys_id"), status: otherScheds.getValue("status") });
            }
        }

        var scenarioId = this._createScenario({
            scenario_name: "Schedule Shift: " + poNumber + " by " + shiftDays + " day(s)",
            disruption_category: "urgent_order_ingestion",
            target_entity: poNumber,
            disruption_parameter: "Shift " + (shiftDays > 0 ? "delayed" : "advanced") + " by " + Math.abs(shiftDays) + " day(s)",
            impacted_order_count: 1,
            recommended_strategy: conflictsFound.length > 0 ? "Resolve resource conflicts before applying shift" : "Shift is feasible"
        });

        return {
            success: true,
            scenario_type: "schedule_shift",
            scenario_sys_id: scenarioId,
            production_order: poNumber,
            schedule_sys_id: schedId,
            schedule_status: schedStatus,
            original_start: originalStart,
            original_end: originalEnd,
            simulated_start: simStart.getValue(),
            simulated_end: simEnd.getValue(),
            shift_days: shiftDays,
            resource_conflicts: conflictsFound,
            message: "Schedule for " + poNumber + " shifted by " + shiftDays + " day(s). " + (conflictsFound.length > 0 ? conflictsFound.length + " resource conflict(s) detected." : "No resource conflicts.")
        };
    },

    // ═══════════════════════════════════════
    // HELPERS (READ-ONLY)
    // ═══════════════════════════════════════

    _getActiveSchedulesForResource: function(resId) {
        var results = [];
        var gr = new GlideRecord(this.SCHED);
        gr.addQuery("production_resource", resId);
        gr.addQuery("status", "IN", "draft,scheduled,confirmed,in_progress");
        gr.query();
        while (gr.next()) {
            var poGr = new GlideRecord(this.PO);
            var poNum = "";
            var deliveryDeadline = "";
            if (poGr.get(gr.getValue("production_order"))) {
                poNum = poGr.getValue("number");
                // Resolve delivery deadline: customer date first, else PO planned_end
                var coId = poGr.getValue("customer_order");
                if (coId) {
                    var co = new GlideRecord("x_2056099_indust_0_cust_order");
                    if (co.get(coId)) deliveryDeadline = co.getValue("requested_delivery_date") || "";
                }
                if (!deliveryDeadline) deliveryDeadline = poGr.getValue("planned_end_date") || "";
            }
            results.push({
                sys_id: gr.getValue("sys_id"),
                status: gr.getValue("status"),
                po_number: poNum,
                po_sys_id: gr.getValue("production_order"),
                planned_quantity: parseFloat(gr.getValue("planned_quantity")) || 0,
                planned_start: gr.getValue("planned_start"),
                planned_end: gr.getValue("planned_end"),
                delivery_deadline: deliveryDeadline
            });
        }
        return results;
    },

    _findAlternateResources: function(excludeResId) {
        var results = [];
        var gr = new GlideRecord(this.RES);
        gr.addQuery("sys_id", "!=", excludeResId);
        gr.addQuery("active", true);
        gr.addQuery("status", "available");
        gr.addQuery("maintenance_required", false);
        gr.orderByDesc("capacity_per_day");
        gr.query();
        while (gr.next()) {
            results.push({
                sys_id: gr.getValue("sys_id"),
                resource_name: gr.getValue("resource_name"),
                resource_id: gr.getValue("resource_id"),
                capacity_per_day: parseFloat(gr.getValue("capacity_per_day")) || 0,
                efficiency: parseFloat(gr.getValue("efficiency_percentage")) || 100
            });
        }
        return results;
    },

    _calcDays: function(qty, capacity, efficiency) {
        var eff = (efficiency || 100) / 100;
        var effective = (capacity || 1) * eff;
        if (effective <= 0) effective = 1;
        return Math.ceil(qty / effective);
    },

    _createScenario: function(data) {
        var gr = new GlideRecord(this.SCENARIO);
        gr.initialize();
        gr.setValue("scenario_name", data.scenario_name || "");
        gr.setValue("scenario_id", "SIM-" + new GlideDateTime().getNumericValue());
        gr.setValue("disruption_category", data.disruption_category || "");
        gr.setValue("target_entity", data.target_entity || "");
        gr.setValue("disruption_parameter", data.disruption_parameter || "");
        gr.setValue("simulation_status", "evaluated");
        gr.setValue("impacted_order_count", data.impacted_order_count || 0);
        gr.setValue("recommended_strategy", data.recommended_strategy || "");
        return gr.insert() || "";
    },

    _createRunRecord: function(scenarioId, schedData, proposal) {
        var gr = new GlideRecord(this.RUN);
        gr.initialize();
        gr.setValue("scenario", scenarioId);
        gr.setValue("customer_order_ref", schedData.po_number || "");
        gr.setValue("order_qty", schedData.planned_quantity || 0);
        gr.setValue("assigned_machine", proposal.current_resource || "");
        // Determine adaptive_strategy: prefer resource_name, fall back to resource_id
        var strategyLabel = "";
        if (proposal.proposed_resource) {
            strategyLabel = "Reschedule to " + proposal.proposed_resource;
        } else if (proposal.proposed_resource_id) {
            var altRes = new GlideRecord(this.RES);
            if (altRes.get(proposal.proposed_resource_id)) {
                strategyLabel = "Reschedule to " + (altRes.getValue("resource_id") || proposal.proposed_resource_id);
            }
        }
        gr.setValue("adaptive_strategy", strategyLabel || "Manual review");
        gr.setValue("material_status", "in_stock");
        // Populate date/delivery fields from the virtual proposal calculation
        if (schedData.planned_end) gr.setValue("baseline_planned_finish", schedData.planned_end);
        if (proposal.proposed_end) {
            gr.setValue("simulated_finish", proposal.proposed_end);
            gr.setValue("adapted_finish", proposal.proposed_end);
        }
        if (proposal.delivery_status) {
            gr.setValue("final_otd_status", proposal.delivery_status);
        }
        if (typeof proposal.delay_days === "number") {
            // net_delay_recovered = original duration minus simulated (positive = faster)
            gr.setValue("delay_unmitigated", proposal.delay_days > 0 ? proposal.delay_days : 0);
            // If the proposal is on time, any original schedule slip is recovered
            var origEnd = schedData.planned_end ? new GlideDateTime(schedData.planned_end) : null;
            var propEnd = proposal.proposed_end ? new GlideDateTime(proposal.proposed_end) : null;
            if (origEnd && propEnd) {
                var recoveredMs = GlideDateTime.subtract(propEnd, origEnd).getNumericValue();
                var recoveredDays = Math.max(0, Math.ceil(recoveredMs / (1000 * 60 * 60 * 24)));
                gr.setValue("net_delay_recovered", recoveredDays);
            }
        }
        return gr.insert() || "";
    },

    /**
     * Safely applies a What-If simulation proposal to live production schedules and orders.
     * Non-destructive fallback: If anything fails, aborts cleanly without corrupting state.
     *
     * @param {object} params - {
     *   schedule_sys_id: string,
     *   production_order_sys_id: string,
     *   proposed_resource_id: string,
     *   proposed_start: string,
     *   proposed_end: string,
     *   simulation_run_sys_id: string (optional)
     * }
     */
    applyProposal: function(params) {
        if (!params) {
            return this._fail("Parameters required to apply proposal.");
        }
        var schedSysId = params.schedule_sys_id || "";
        var poSysId = params.production_order_sys_id || "";

        try {
            // Set session transition flag for lifecycle guard BR
            gs.getSession().putClientData("x_2056099_indust_0_api_transition", "confirm");

            var schedGr = new GlideRecord(this.SCHED);
            var found = false;
            if (schedSysId && schedGr.get(schedSysId)) {
                found = true;
            } else if (poSysId) {
                schedGr.addQuery("production_order", poSysId);
                schedGr.addQuery("status", "IN", "draft,scheduled,confirmed");
                schedGr.setLimit(1);
                schedGr.query();
                if (schedGr.next()) found = true;
            }

            if (!found) {
                return this._fail("Active Production Schedule not found for target parameters.");
            }

            var schedNum = schedGr.getValue("number") || schedGr.getUniqueValue();
            var currStatus = schedGr.getValue("status");

            if (currStatus === "completed" || currStatus === "cancelled") {
                return this._fail("Cannot modify schedule " + schedNum + " in terminal status: " + currStatus);
            }

            var newResName = "";
            if (params.proposed_resource_id) {
                var resGr = new GlideRecord(this.RES);
                if (resGr.get(params.proposed_resource_id)) {
                    schedGr.setValue("production_resource", params.proposed_resource_id);
                    newResName = resGr.getValue("resource_name") || resGr.getValue("resource_id");
                }
            }

            if (params.proposed_start) schedGr.setValue("planned_start", params.proposed_start);
            if (params.proposed_end) schedGr.setValue("planned_end", params.proposed_end);

            if (currStatus === "draft") {
                schedGr.setValue("status", "scheduled");
            }
            schedGr.setValue("reschedule_reason", "Adaptive What-If Plan Applied");
            schedGr.update();

            // Safely sync with linked production order
            var linkedPo = schedGr.getValue("production_order");
            if (linkedPo) {
                var poGr = new GlideRecord(this.PO);
                if (poGr.get(linkedPo)) {
                    if (params.proposed_resource_id) {
                        poGr.setValue("assigned_resource", params.proposed_resource_id);
                    }
                    if (params.proposed_end) {
                        poGr.setValue("planned_completion_date", params.proposed_end);
                    }
                    poGr.update();
                }
            }

            return {
                success: true,
                message: "Applied What-If proposal to Schedule " + schedNum + (newResName ? " (Reassigned to " + newResName + ")" : ""),
                schedule_sys_id: schedGr.getUniqueValue(),
                schedule_number: schedNum,
                new_resource: newResName,
                new_start: schedGr.getValue("planned_start"),
                new_end: schedGr.getValue("planned_end"),
                status: schedGr.getValue("status")
            };
        } catch (ex) {
            return this._fail("Error applying proposal: " + ex.message);
        }
    },

    _fail: function(reason) {
        return { success: false, error: reason };
    },

    type: "WhatIfSimulationEngine"
};
